// Registering LeadForge qualification tool with the MCP Server
server.setRequestHandler(ListToolsRequestSchema, async () => ({
  tools: [
    {
      name: 'qualify_lead',
      description: 'Scores a lead against ideal customer profile parameters',
      inputSchema: {
        type: 'object',
        properties: {
          domain: { type: 'string' },
          contact_title: { type: 'string' },
          annual_revenue_range: { type: 'string' }
        },
        required: ['domain']
      }
    }
  ]
}));
